import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

void main() {
  group('HomePage refresh all', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();
    final MockSettingsRepository mockSettingsRepository = MockSettingsRepository();

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => const CurrencyPage(items: [], page: 0, hasMore: false));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => []);
      when(mockNewsRepository.saveNewsList(any)).thenAnswer((_) async {});
      when(mockSettingsRepository.readThemeMode()).thenReturn(AppThemeMode.system);
    });

    testWidgets('should refresh currency and news from network when refresh all is tapped', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
            Provider<SettingsRepository>.value(value: mockSettingsRepository),
          ],
          child: const HomePage(),
        ),
      );
      await tester.pump();

      final int initialCurrencyCalls = verify(mockCurrencyRepository.fetchRates(any)).callCount;
      final int initialNewsCalls = verify(mockNewsRepository.loadNewsFeed(any)).callCount;
      expect(initialCurrencyCalls, 1);
      expect(initialNewsCalls, 1);

      await tester.tap(find.byIcon(Icons.refresh));
      await tester.pump();
      await tester.pump();

      // «Обновить всё»: и курс валют, и лента новостей повторно идут в сеть.
      expect(verify(mockCurrencyRepository.fetchRates(any)).callCount, initialCurrencyCalls + 1);
      expect(verify(mockNewsRepository.loadNewsFeed(any)).callCount, initialNewsCalls + 1);
      verify(mockCurrencyRepository.saveCurrencyList(any)).called(2);
    });
  });
}
